// Three notes -> three items, each with an ISO-8601 post_time WITH an explicit offset
// (schedule_post rejects naive datetimes; see the sticky note).
const s = $input.first().json;
const notes = [s.note_1, s.note_2, s.note_3].filter(n => n && String(n).trim());
const days = String(s.post_days || '2,4,6').split(',').map(d => parseInt(d.trim(), 10));
const hour = Number(s.post_hour ?? 9);
const offset = String(s.utc_offset || '+00:00');
const pad = n => String(n).padStart(2, '0');
const now = new Date();
function nextWeekday(isoDay, fromDate) {
  const d = new Date(fromDate);
  const current = ((d.getUTCDay() + 6) % 7) + 1; // 1=Mon..7=Sun
  let diff = isoDay - current; if (diff <= 0) diff += 7;
  d.setUTCDate(d.getUTCDate() + diff);
  return d;
}
return notes.map((note, i) => {
  const d = nextWeekday(days[i % days.length], now);
  const post_time = `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}T${pad(hour)}:00:00${offset}`;
  return { json: { note, post_time, index: i + 1 } };
});

// The agent answers with one JSON object; strip code fences if the model added them.
const raw = String($json.output ?? $json.text ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let brief;
try { brief = JSON.parse(raw); } catch (e) { throw new Error('Agent did not return JSON: ' + raw.slice(0, 300)); }
const style = ['authority', 'proof', 'growth'].includes(brief.style) ? brief.style : 'proof';
const src = $('Loop Over Notes').item.json;
return [{ json: {
  user_idea: String(brief.user_idea || src.note),
  style,
  user_constraints: brief.user_constraints ? String(brief.user_constraints) : undefined,
  post_time: src.post_time,
  note: src.note,
}}];

// MCP Client node output -> flat item (structuredContent is the tool's result).
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  let data = j.structuredContent;
  if (data === undefined) {
    const first = Array.isArray(j.content) ? j.content[0] : undefined;
    data = (first && typeof first === 'object' && !('type' in first)) ? first : (first?.text ?? j);
    if (typeof data === 'string') { try { data = JSON.parse(data); } catch { data = { text: data }; } }
  }
  if (data?.status === 'error') throw new Error(`ContentIn refused the call (${data.code}): ${JSON.stringify(data)}`);
  out.push({ json: data });
}
return out;

