// The confirm token lives 5 minutes; Slack approval can take longer. So we fetch a
// fresh token and only use it if the text is byte-identical to what the human approved.
const approved = $('Parse preview').item.json;
const fresh = $json;
const same = String(approved.exact_text) === String(fresh.exact_text) && approved.post_id === fresh.post_id;
return [{ json: { same, post_id: fresh.post_id, confirm_token: fresh.confirm_token, post_time: $('Parse brief').item.json.post_time, exact_text: fresh.exact_text } }];

